const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "sqlite",
  "inlineSchema": "// =============================================================================\n// DivergenCIE — Sandbox Prisma Schema v6.0\n// Ground Truth: DC Database 2026.xlsx + UJM v6.0\n// decisions: Q1–Q21 locked.\n// Engine: SQLite (dev) / PostgreSQL (prod) — syntax compatible with both\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/sandbox\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ─── CLUSTER 1 — USERS & PROFILES ───────────────────────────────────────────\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  name           String?\n  role           String?\n  dept           String?\n  supervisor     Boolean  @default(false)\n  passwordHash   String?\n  photo          String?\n  bio            String?\n  isActive       Boolean  @default(true)\n  referralCode   String?  @unique\n  whatsappNumber String?\n  country        String?\n  createdAt      DateTime @default(now())\n\n  // Parent–student self-join\n  parentId String?\n  parent   User?   @relation(\"ParentStudent\", fields: [parentId], references: [id])\n  children User[]  @relation(\"ParentStudent\")\n\n  // Profile relations (one per role, all optional)\n  studentProfile    StudentProfile?\n  teacherProfile    TeacherProfile?\n  staffProfile      StaffProfile?\n  parentProfile     ParentProfile?\n  ambassadorProfile AmbassadorProfile?\n\n  // Bank accounts\n  bankAccounts BankAccount[]\n\n  // Tickets\n  ticketsCreated  Ticket[]        @relation(\"TicketCreator\")\n  ticketsAssigned Ticket[]        @relation(\"TicketAssignee\")\n  ticketMessages  TicketMessage[]\n  ticketHistory   TicketHistory[]\n\n  // Meetings & Events\n  meetingParticipants MeetingParticipant[]\n  calendarItems       CalendarItem[]\n\n  // Other CRM logs\n  siteLogs            SiteLog[]\n  studentFlags        StudentFlag[]     @relation(\"FlaggedUser\")\n  studentFlagsCreated StudentFlag[]     @relation(\"FlagCreator\")\n  accessLogs          AccessLog[]\n  contentBankItems    ContentBankItem[]\n\n  // Records\n  studentRecords      StudentRecord[]    @relation(\"StudentRecordUser\")\n  studentRecordsIssue StudentRecord[]    @relation(\"StudentRecordIssuer\")\n  teacherRecords      TeacherRecord[]    @relation(\"TeacherRecordUser\")\n  teacherRecordsIssue TeacherRecord[]    @relation(\"TeacherRecordIssuer\")\n  staffRecords        StaffRecord[]      @relation(\"StaffRecordUser\")\n  staffRecordsIssued  StaffRecord[]      @relation(\"StaffRecordIssuer\")\n  ambassadorRecords   AmbassadorRecord[] @relation(\"AmbassadorRecordUser\")\n  ambassadorRecordIss AmbassadorRecord[] @relation(\"AmbassadorRecordIssuer\")\n\n  // Enrollments\n  studentEnrolmentLists     StudentEnrolmentList[]\n  teacherEnrolmentLists     TeacherEnrolmentList[]\n  staffEnrolmentLists       StaffEnrolmentList[]\n  ambassadorEnrolmentLists  AmbassadorEnrolmentList[]\n  ambassadorCommissionLists AmbassadorCommissionList[]\n\n  // Accounting & Billings\n  studentInvoices     StudentInvoice[]\n  paymentRecords      PaymentRecord[]\n  claims              Claim[]\n  paychecks           Paycheck[]           @relation(\"PaycheckRecipient\")\n  ambassadorClaims    AmbassadorClaim[]\n  ambassadorPaychecks AmbassadorPaycheck[]\n\n  // Services & Academics\n  services                    Service[]\n  taughtSessions              AcademicSession[]             @relation(\"TeacherSessions\")\n  attendances                 SessionAttendance[]\n  taskAssignments             TaskAssignment[]\n  taskSubmissions             TaskSubmission[]\n  mockResults                 MockResult[]\n  doubts                      Doubt[]\n  studentProgress             StudentProgress[]\n  assignments                 Assignment[]\n  ambassadorProgrammeProgress AmbassadorProgrammeProgress[]\n  referrals                   Referral[]                    @relation(\"Referrer\")\n  ambassadorTestRes           AmbassadorTestResult[]\n  checklistEntries            ChecklistEntry[]\n\n  @@index([isActive])\n}\n\nmodel StudentProfile {\n  id                   String    @id @default(cuid())\n  userId               String    @unique\n  user                 User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  status               String    @default(\"ACTIVE\") // \"ACTIVE\" | \"PAUSED\" | \"CANCELLED\" | \"COMPLETED\"\n  firstName            String?\n  lastName             String?\n  school               String?\n  whatsappNumber       String?\n  parentWhatsappNumber String?\n  gcrLink              String?\n  location             String?\n  mainCurrency         String?\n  timeZone             String?\n  notes                String?\n  referredBy           String?\n  timesheetURL         String?\n  scheduleURL          String?\n  progressTrackerURL   String?\n  gcrAssigned          Boolean   @default(false)\n  groupAssigned        Boolean   @default(false)\n  scheduleAssigned     Boolean   @default(false)\n  financeApprovedFlag  Boolean   @default(false)\n  registrationDate     DateTime  @default(now())\n  cancellationReason   String?\n  dob                  DateTime?\n  grade                String?\n  board                String?\n}\n\nmodel TeacherProfile {\n  id                    String  @id @default(cuid())\n  userId                String  @unique\n  user                  User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  firstName             String?\n  lastName              String?\n  teachingProfileUrl    String?\n  idDocProvided         Boolean @default(false)\n  salaryAccountProvided Boolean @default(false)\n}\n\nmodel StaffProfile {\n  id               String    @id @default(cuid())\n  userId           String    @unique\n  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  status           String    @default(\"ACTIVE\") // \"ACTIVE\" | \"PAUSED\" | \"CANCELLED\" | \"COMPLETED\"\n  roleTitle        String?\n  salaryType       String?\n  salaryRate       Float?\n  role             String?\n  dept             String?\n  isSupervisor     Boolean   @default(false)\n  registrationDate DateTime  @default(now())\n  departedAt       DateTime?\n  departureReason  String?\n}\n\nmodel ParentProfile {\n  id      String  @id @default(cuid())\n  userId  String  @unique\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  phone   String?\n  address String?\n}\n\nmodel AmbassadorProfile {\n  id                String    @id @default(cuid())\n  userId            String    @unique\n  user              User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  cohort            String?\n  referralCode      String?   @unique\n  programmeDuration String?\n  programmeStart    DateTime?\n  programmeEnd      DateTime?\n  completionStatus  String?\n  certificateLink   String?\n  linkedInBadgeLink String?\n\n  deliverables AmbassadorDeliverable[]\n  earnings     AmbassadorEarning[]\n}\n\n// ─── CLUSTER 2 — PRE-HIRE PIPELINE ──────────────────────────────────────────\n\nmodel Candidate {\n  id                   String    @id @default(cuid())\n  email                String    @unique\n  name                 String\n  candidateType        String? // \"TEACHER\" | \"STAFF\" | \"AMBASSADOR\" | \"STUDENT\"\n  role                 String\n  status               String    @default(\"APPLIED\") // \"APPLIED\" | \"SCREENING\" etc.\n  cvLink               String?\n  docsLink             String?\n  notes                String?\n  outreachSource       String?\n  outreachStatus       String?\n  trialTaskLink        String?\n  interviewAt          DateTime?\n  convertedToUserId    String?\n  isActive             Boolean   @default(true)\n  outreach             String?\n  skills               String?\n  extraSkills          String?\n  qualifications       String?\n  expectedRate         String?\n  timeZone             String?\n  interviewTime        String?\n  startDate            DateTime?\n  offerLetterStatus    String?\n  gcrAccess            String?\n  classSchedule        String?\n  workFolder           String?\n  interviewRequestedAt DateTime?\n\n  registrationEntries RegistrationFormEntry[]\n}\n\n// ─── CLUSTER 3 — SESSION TYPES ──────────────────────────────────────────────\n\nmodel SessionType {\n  id       String  @id @default(cuid())\n  name     String  @unique // \"CLASS\" | \"MOCK\" | \"TRIAL\" | \"EXAM\"\n  isActive Boolean @default(true)\n\n  scheduleOccurrences   ScheduleOccurrence[]\n  staffOccurrences      StaffScheduleOccurrence[]\n  ambassadorOccurrences AmbassadorScheduleOccurrence[]\n  academicSessions      AcademicSession[]\n  meetings              Meeting[]\n  ambassadorMeetings    AmbassadorMeeting[]\n  generalMeetings       GeneralMeeting[]\n}\n\n// ─── CLUSTER 4 — GROUPS & SERVICES ──────────────────────────────────────────\n\nmodel Group {\n  id            String   @id @default(cuid())\n  code          String   @unique // \"B8\", \"C14\"\n  groupCategory String // \"B_GROUP\" | \"C_GROUP\" | \"T_GROUP\"\n  status        String   @default(\"active\")\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n\n  services Service[]\n  sessions AcademicSession[]\n}\n\nmodel Service {\n  id                     String  @id @default(cuid())\n  groupId                String?\n  group                  Group?  @relation(fields: [groupId], references: [id])\n  teacherId              String\n  teacher                User    @relation(fields: [teacherId], references: [id])\n  board                  String?\n  courseLevel            String?\n  subjectCode            String?\n  subjectName            String\n  fullSubjectName        String?\n  standardRate           Float?\n  instructorNameSnapshot String?\n  serviceType            String // \"HOURLY_FIXED\" | \"HOURLY_FLEXIBLE\" | \"MONTHLY\" | \"ONE_OFF\"\n  isHourly               Boolean @default(false)\n  teacherIdSnapshot      String?\n  isActive               Boolean @default(true)\n  currency               String?\n\n  rateList              RateList?\n  studentEnrolmentItems StudentEnrolmentItem[]\n  teacherEnrolmentItems TeacherEnrolmentItem[]\n  serviceSchedules      ServiceSchedule[]\n  academicSessions      AcademicSession[]\n  attendances           SessionAttendance[]\n  recordings            Recording[]\n  curriculumLists       CurriculumList[]\n  taskItems             TaskItem[]\n  mockItems             MockItem[]\n  assignments           Assignment[]\n  mockResults           MockResult[]\n  claimLineItems        ClaimLineItem[]\n}\n\n// ─── CLUSTER 5 — RATE SYSTEM ────────────────────────────────────────────────\n\nmodel RateList {\n  id        String  @id @default(cuid())\n  serviceId String  @unique\n  service   Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n  isActive  Boolean @default(true)\n\n  rateItems RateItem[]\n}\n\nmodel RateItem {\n  id            String    @id @default(cuid())\n  rateListId    String\n  rateList      RateList  @relation(fields: [rateListId], references: [id], onDelete: Cascade)\n  country       String // \"MY\" | \"IN\" | \"PK\" | \"GB\" | \"SA\" | \"DEFAULT\"\n  currency      String\n  clientRate    Float\n  staffRate     Float?\n  status        String    @default(\"ACTIVE\") // \"ACTIVE\" | \"PAUSED\" | \"INACTIVE\"\n  activatedAt   DateTime  @default(now())\n  pausedAt      DateTime?\n  deactivatedAt DateTime?\n  isActive      Boolean   @default(true)\n\n  history RateItemStatusHistory[]\n  changes RateChangeLog[]\n}\n\nmodel RateItemStatusHistory {\n  id              String   @id @default(cuid())\n  rateItemId      String\n  rateItem        RateItem @relation(fields: [rateItemId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel RateChangeLog {\n  id                 String   @id @default(cuid())\n  rateItemId         String\n  rateItem           RateItem @relation(fields: [rateItemId], references: [id], onDelete: Cascade)\n  previousClientRate Float\n  newClientRate      Float\n  previousStaffRate  Float?\n  newStaffRate       Float?\n  changedAt          DateTime @default(now())\n  changedByUserId    String\n  reason             String?\n}\n\n// ─── CLUSTER 6 — STUDENT ENROLMENT ──────────────────────────────────────────\n\nmodel StudentEnrolmentList {\n  id          String  @id @default(cuid())\n  studentId   String\n  student     User    @relation(fields: [studentId], references: [id])\n  serviceType String\n  isActive    Boolean @default(true)\n\n  items StudentEnrolmentItem[]\n}\n\nmodel StudentEnrolmentItem {\n  id                    String               @id @default(cuid())\n  enrolmentListId       String\n  enrolmentList         StudentEnrolmentList @relation(fields: [enrolmentListId], references: [id], onDelete: Cascade)\n  studentId             String\n  serviceId             String\n  service               Service              @relation(fields: [serviceId], references: [id])\n  status                String               @default(\"ACTIVE\") // \"TRIAL\" | \"ACTIVE\" | \"CANCELLED\"\n  trialRequired         Boolean              @default(false)\n  startDate             DateTime?\n  endDate               DateTime?\n  expectedHoursPerMonth Float?\n  activatedAt           DateTime?\n  cancelledAt           DateTime?\n  completedAt           DateTime?\n  cancellationReason    String?\n  isActive              Boolean              @default(true)\n\n  history          StudentEnrolmentItemStatusHistory[]\n  discounts        Discount[]\n  attendances      SessionAttendance[]\n  invoiceLineItems InvoiceLineItem[]\n  commissionItems  AmbassadorCommissionItem[]\n}\n\nmodel StudentEnrolmentItemStatusHistory {\n  id              String               @id @default(cuid())\n  enrolmentItemId String\n  enrolmentItem   StudentEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime             @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel Discount {\n  id              String                @id @default(cuid())\n  studentId       String\n  enrolmentItemId String?\n  enrolmentItem   StudentEnrolmentItem? @relation(fields: [enrolmentItemId], references: [id])\n  discountType    String\n  value           Float\n  isPct           Boolean               @default(true)\n  code            String?\n  isActive        Boolean               @default(true)\n}\n\n// ─── CLUSTER 7 — TEACHER ENROLMENT ──────────────────────────────────────────\n\nmodel TeacherEnrolmentList {\n  id          String  @id @default(cuid())\n  teacherId   String\n  teacher     User    @relation(fields: [teacherId], references: [id])\n  serviceType String\n  isActive    Boolean @default(true)\n\n  items TeacherEnrolmentItem[]\n}\n\nmodel TeacherEnrolmentItem {\n  id                 String               @id @default(cuid())\n  enrolmentListId    String\n  enrolmentList      TeacherEnrolmentList @relation(fields: [enrolmentListId], references: [id], onDelete: Cascade)\n  teacherId          String\n  serviceId          String\n  service            Service              @relation(fields: [serviceId], references: [id])\n  status             String               @default(\"ACTIVE\")\n  trialRequired      Boolean              @default(false)\n  startDate          DateTime?\n  endDate            DateTime?\n  activatedAt        DateTime?\n  cancelledAt        DateTime?\n  completedAt        DateTime?\n  cancellationReason String?\n  isActive           Boolean              @default(true)\n\n  history TeacherEnrolmentItemStatusHistory[]\n}\n\nmodel TeacherEnrolmentItemStatusHistory {\n  id              String               @id @default(cuid())\n  enrolmentItemId String\n  enrolmentItem   TeacherEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime             @default(now())\n  changedByUserId String\n  reason          String?\n}\n\n// ─── CLUSTER 8 — STAFF ENROLMENT ────────────────────────────────────────────\n\nmodel StaffEnrolmentList {\n  id          String  @id @default(cuid())\n  staffId     String\n  staff       User    @relation(fields: [staffId], references: [id])\n  serviceType String\n  isActive    Boolean @default(true)\n\n  items StaffEnrolmentItem[]\n}\n\nmodel StaffEnrolmentItem {\n  id                    String             @id @default(cuid())\n  enrolmentListId       String\n  enrolmentList         StaffEnrolmentList @relation(fields: [enrolmentListId], references: [id], onDelete: Cascade)\n  staffId               String\n  staffServiceId        String // linked conceptually\n  status                String             @default(\"ACTIVE\")\n  trialRequired         Boolean            @default(false)\n  startDate             DateTime?\n  endDate               DateTime?\n  expectedHoursPerMonth Float?\n  activatedAt           DateTime?\n  cancelledAt           DateTime?\n  completedAt           DateTime?\n  cancellationReason    String?\n  isActive              Boolean            @default(true)\n\n  history            StaffEnrolmentItemStatusHistory[]\n  meetingAttendances MeetingAttendance[]\n}\n\nmodel StaffEnrolmentItemStatusHistory {\n  id              String             @id @default(cuid())\n  enrolmentItemId String\n  enrolmentItem   StaffEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime           @default(now())\n  changedByUserId String\n  reason          String?\n}\n\n// ─── CLUSTER 9 — AMBASSADOR ENROLMENT & COMMISSION ──────────────────────────\n\nmodel AmbassadorEnrolmentList {\n  id           String  @id @default(cuid())\n  ambassadorId String\n  ambassador   User    @relation(fields: [ambassadorId], references: [id])\n  serviceType  String\n  isActive     Boolean @default(true)\n\n  items AmbassadorEnrolmentItem[]\n}\n\nmodel AmbassadorEnrolmentItem {\n  id                  String                  @id @default(cuid())\n  enrolmentListId     String\n  enrolmentList       AmbassadorEnrolmentList @relation(fields: [enrolmentListId], references: [id], onDelete: Cascade)\n  ambassadorId        String\n  ambassadorServiceId String\n  status              String                  @default(\"ACTIVE\")\n  trialRequired       Boolean                 @default(false)\n  startDate           DateTime?\n  endDate             DateTime?\n  activatedAt         DateTime?\n  cancelledAt         DateTime?\n  completedAt         DateTime?\n  cancellationReason  String?\n  isActive            Boolean                 @default(true)\n\n  history            AmbassadorEnrolmentItemStatusHistory[]\n  meetingAttendances AmbassadorMeetingAttendance[]\n}\n\nmodel AmbassadorEnrolmentItemStatusHistory {\n  id              String                  @id @default(cuid())\n  enrolmentItemId String\n  enrolmentItem   AmbassadorEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime                @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel AmbassadorCommissionList {\n  id           String  @id @default(cuid())\n  ambassadorId String\n  ambassador   User    @relation(fields: [ambassadorId], references: [id])\n  isActive     Boolean @default(true)\n\n  items AmbassadorCommissionItem[]\n}\n\nmodel AmbassadorCommissionItem {\n  id                     String                   @id @default(cuid())\n  commissionListId       String\n  commissionList         AmbassadorCommissionList @relation(fields: [commissionListId], references: [id], onDelete: Cascade)\n  studentEnrolmentItemId String\n  studentEnrolmentItem   StudentEnrolmentItem     @relation(fields: [studentEnrolmentItemId], references: [id])\n  commissionPct          Float\n  status                 String                   @default(\"ACTIVE\")\n  activatedAt            DateTime                 @default(now())\n  pausedAt               DateTime?\n  deactivatedAt          DateTime?\n  isActive               Boolean                  @default(true)\n\n  history AmbassadorCommissionItemStatusHistory[]\n  changes AmbassadorCommissionRateChangeLog[]\n}\n\nmodel AmbassadorCommissionItemStatusHistory {\n  id               String                   @id @default(cuid())\n  commissionItemId String\n  commissionItem   AmbassadorCommissionItem @relation(fields: [commissionItemId], references: [id], onDelete: Cascade)\n  fromStatus       String\n  toStatus         String\n  changedAt        DateTime                 @default(now())\n  changedByUserId  String\n  reason           String?\n}\n\nmodel AmbassadorCommissionRateChangeLog {\n  id               String                   @id @default(cuid())\n  commissionItemId String\n  commissionItem   AmbassadorCommissionItem @relation(fields: [commissionItemId], references: [id], onDelete: Cascade)\n  previousPct      Float\n  newPct           Float\n  changedAt        DateTime                 @default(now())\n  changedByUserId  String\n  reason           String?\n}\n\n// ─── CLUSTER 10 — SCHEDULES (STUDENT) ───────────────────────────────────────\n\nmodel ServiceSchedule {\n  id        String  @id @default(cuid())\n  serviceId String  @unique\n  service   Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n  isActive  Boolean @default(true)\n\n  occurrences    ScheduleOccurrence[]\n  changeRequests ScheduleChangeRequest[]\n}\n\nmodel ScheduleOccurrence {\n  id             String          @id @default(cuid())\n  scheduleId     String\n  schedule       ServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  sessionTypeId  String\n  sessionType    SessionType     @relation(fields: [sessionTypeId], references: [id])\n  recurrenceType String // \"WEEKLY\" | \"BIWEEKLY\" | \"ONE_OFF\" etc.\n  dayOfWeek      String?\n  dayOfMonth     Int?\n  monthOfYear    String?\n  oneOffDate     DateTime?\n  customPattern  String?\n  startTime      DateTime\n  endTime        DateTime\n  durationHours  Float\n  status         String          @default(\"ACTIVE\")\n  activatedAt    DateTime        @default(now())\n  pausedAt       DateTime?\n  deactivatedAt  DateTime?\n  isActive       Boolean         @default(true)\n\n  history ScheduleOccurrenceStatusHistory[]\n}\n\nmodel ScheduleOccurrenceStatusHistory {\n  id              String             @id @default(cuid())\n  occurrenceId    String\n  occurrence      ScheduleOccurrence @relation(fields: [occurrenceId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime           @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel ScheduleChangeRequest {\n  id                    String          @id @default(cuid())\n  scheduleId            String\n  schedule              ServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  occurrenceId          String?\n  requestedByUserId     String\n  requestType           String // \"ADD\" | \"REMOVE\" | \"RESCHEDULE\"\n  recurrenceType        String\n  proposedDayOfWeek     String?\n  proposedStartTime     DateTime?\n  proposedEndTime       DateTime?\n  proposedDuration      Float?\n  proposedSessionTypeId String?\n  status                String          @default(\"PENDING\")\n  rejectionReason       String?\n  resolvedAt            DateTime?\n  resolvedByUserId      String?\n}\n\n// ─── CLUSTER 10B — SCHEDULES (STAFF) ────────────────────────────────────────\n\nmodel StaffServiceSchedule {\n  id             String  @id @default(cuid())\n  staffServiceId String  @unique\n  isActive       Boolean @default(true)\n\n  occurrences    StaffScheduleOccurrence[]\n  changeRequests StaffScheduleChangeRequest[]\n}\n\nmodel StaffScheduleOccurrence {\n  id             String               @id @default(cuid())\n  scheduleId     String\n  schedule       StaffServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  sessionTypeId  String\n  sessionType    SessionType          @relation(fields: [sessionTypeId], references: [id])\n  recurrenceType String\n  dayOfWeek      String?\n  dayOfMonth     Int?\n  monthOfYear    String?\n  oneOffDate     DateTime?\n  customPattern  String?\n  startTime      DateTime\n  endTime        DateTime\n  durationHours  Float\n  status         String               @default(\"ACTIVE\")\n  activatedAt    DateTime             @default(now())\n  pausedAt       DateTime?\n  deactivatedAt  DateTime?\n  isActive       Boolean              @default(true)\n\n  history StaffScheduleOccurrenceStatusHistory[]\n}\n\nmodel StaffScheduleOccurrenceStatusHistory {\n  id              String                  @id @default(cuid())\n  occurrenceId    String\n  occurrence      StaffScheduleOccurrence @relation(fields: [occurrenceId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime                @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel StaffScheduleChangeRequest {\n  id                    String               @id @default(cuid())\n  scheduleId            String\n  schedule              StaffServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  occurrenceId          String?\n  requestedByUserId     String\n  requestType           String\n  recurrenceType        String\n  proposedDayOfWeek     String?\n  proposedStartTime     DateTime?\n  proposedEndTime       DateTime?\n  proposedDuration      Float?\n  proposedSessionTypeId String?\n  status                String               @default(\"PENDING\")\n  rejectionReason       String?\n  resolvedAt            DateTime?\n  resolvedByUserId      String?\n}\n\n// ─── CLUSTER 10C — SCHEDULES (AMBASSADOR) ───────────────────────────────────\n\nmodel AmbassadorServiceSchedule {\n  id                  String  @id @default(cuid())\n  ambassadorServiceId String  @unique\n  isActive            Boolean @default(true)\n\n  occurrences    AmbassadorScheduleOccurrence[]\n  changeRequests AmbassadorScheduleChangeRequest[]\n}\n\nmodel AmbassadorScheduleOccurrence {\n  id             String                    @id @default(cuid())\n  scheduleId     String\n  schedule       AmbassadorServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  sessionTypeId  String\n  sessionType    SessionType               @relation(fields: [sessionTypeId], references: [id])\n  recurrenceType String\n  dayOfWeek      String?\n  dayOfMonth     Int?\n  monthOfYear    String?\n  oneOffDate     DateTime?\n  customPattern  String?\n  startTime      DateTime\n  endTime        DateTime\n  durationHours  Float\n  status         String                    @default(\"ACTIVE\")\n  activatedAt    DateTime                  @default(now())\n  pausedAt       DateTime?\n  deactivatedAt  DateTime?\n  isActive       Boolean                   @default(true)\n\n  history AmbassadorScheduleOccurrenceStatusHistory[]\n}\n\nmodel AmbassadorScheduleOccurrenceStatusHistory {\n  id              String                       @id @default(cuid())\n  occurrenceId    String\n  occurrence      AmbassadorScheduleOccurrence @relation(fields: [occurrenceId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime                     @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel AmbassadorScheduleChangeRequest {\n  id                    String                    @id @default(cuid())\n  scheduleId            String\n  schedule              AmbassadorServiceSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  occurrenceId          String?\n  requestedByUserId     String\n  requestType           String\n  recurrenceType        String\n  proposedDayOfWeek     String?\n  proposedStartTime     DateTime?\n  proposedEndTime       DateTime?\n  proposedDuration      Float?\n  proposedSessionTypeId String?\n  status                String                    @default(\"PENDING\")\n  rejectionReason       String?\n  resolvedAt            DateTime?\n  resolvedByUserId      String?\n}\n\n// ─── CLUSTER 11 — ACADEMIC SESSIONS ─────────────────────────────────────────\n\nmodel AcademicSession {\n  id                        String       @id @default(cuid())\n  groupId                   String\n  group                     Group        @relation(fields: [groupId], references: [id])\n  teacherId                 String\n  teacher                   User         @relation(\"TeacherSessions\", fields: [teacherId], references: [id])\n  serviceId                 String\n  service                   Service      @relation(fields: [serviceId], references: [id])\n  serviceScheduleId         String?\n  occurrenceId              String?\n  scheduledByUserId         String?\n  sessionTypeId             String?\n  sessionType               SessionType? @relation(fields: [sessionTypeId], references: [id])\n  topic                     String?\n  startTime                 DateTime\n  endTime                   DateTime\n  originalStartTime         DateTime?\n  originalEndTime           DateTime?\n  durationHours             Float\n  isTrial                   Boolean      @default(false)\n  status                    String       @default(\"SCHEDULED\") // \"SCHEDULED\" | \"COMPLETED\" | \"CANCELLED\"\n  sessionMode               String       @default(\"SCHEDULED\")\n  zoomLink                  String?\n  zoomId                    String?\n  zoomPasscode              String?\n  addedToCalendar           Boolean      @default(false)\n  calendarSyncedAt          DateTime?\n  recordingUrl              String?\n  transcriptUrl             String?\n  summaryUrl                String?\n  wbLink                    String?\n  wbName                    String?\n  timesheetSubmissionStatus String       @default(\"pending\")\n  submissionDeadline        DateTime?\n  submissionOverdue         Boolean      @default(false)\n\n  attendances SessionAttendance[]\n  recordings  Recording[]\n  taskItems   TaskItem[]\n  mockItems   MockItem[]\n}\n\nmodel SessionAttendance {\n  id                   String               @id @default(cuid())\n  sessionId            String\n  session              AcademicSession      @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  serviceId            String\n  service              Service              @relation(fields: [serviceId], references: [id])\n  studentId            String\n  student              User                 @relation(fields: [studentId], references: [id])\n  enrolmentItemId      String\n  enrolmentItem        StudentEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  status               String               @default(\"PRESENT\") // \"PRESENT\" | \"ABSENT_NO_SHOW\" etc.\n  teacherLoggedHours   Float?\n  studentLoggedHours   Float?\n  hoursMatch           Boolean              @default(true)\n  hoursMatchStatus     String               @default(\"MATCHED\")\n  noShowCount          Int                  @default(0)\n  changeRequestPending Boolean              @default(false)\n  changeRequestStatus  String?\n  feedbackStars        Int?\n  feedbackText         String?\n  feedbackGivenAt      DateTime?\n  notes                String?\n  markedAt             DateTime?\n\n  @@unique([sessionId, studentId])\n}\n\n// ─── CLUSTER 12 — STAFF MEETINGS ────────────────────────────────────────────\n\nmodel Meeting {\n  id                     String       @id @default(cuid())\n  staffServiceId         String?\n  staffServiceScheduleId String?\n  occurrenceId           String?\n  scheduledByUserId      String?\n  sessionTypeId          String?\n  sessionType            SessionType? @relation(fields: [sessionTypeId], references: [id])\n  title                  String\n  agenda                 String?\n  startTime              DateTime\n  endTime                DateTime\n  originalStartTime      DateTime?\n  originalEndTime        DateTime?\n  durationHours          Float\n  isTrial                Boolean      @default(false)\n  status                 String       @default(\"scheduled\")\n  sessionMode            String       @default(\"SCHEDULED\")\n  zoomLink               String?\n  zoomId                 String?\n  zoomPasscode           String?\n  addedToCalendar        Boolean      @default(false)\n  calendarSyncedAt       DateTime?\n  recordingUrl           String?\n  transcriptUrl          String?\n  summaryUrl             String?\n  dept                   String?\n  isActive               Boolean      @default(true)\n\n  attendances MeetingAttendance[]\n}\n\nmodel MeetingParticipant {\n  id               String         @id @default(cuid())\n  generalMeetingId String\n  generalMeeting   GeneralMeeting @relation(\"GeneralMeetingParticipants\", fields: [generalMeetingId], references: [id], onDelete: Cascade)\n  userId           String\n  user             User           @relation(fields: [userId], references: [id])\n  rsvp             String         @default(\"pending\") // \"accepted\" | \"declined\" | \"pending\"\n\n  @@unique([generalMeetingId, userId])\n}\n\nmodel MeetingAttendance {\n  id                    String             @id @default(cuid())\n  meetingId             String\n  meeting               Meeting            @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  staffServiceId        String\n  staffId               String\n  enrolmentItemId       String\n  enrolmentItem         StaffEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  status                String\n  staffLoggedHours      Float\n  managementLoggedHours Float\n  hoursMatch            Boolean            @default(true)\n  hoursMatchStatus      String?\n  noShowCount           Int                @default(0)\n  changeRequestPending  Boolean            @default(false)\n  changeRequestStatus   String?\n  feedbackStars         Int?\n  feedbackText          String?\n  feedbackGivenAt       DateTime?\n  notes                 String?\n  markedAt              DateTime?\n}\n\n// ─── CLUSTER 13 — AMBASSADOR MEETINGS ───────────────────────────────────────\n\nmodel AmbassadorMeeting {\n  id                  String       @id @default(cuid())\n  ambassadorServiceId String?\n  scheduleId          String?\n  occurrenceId        String?\n  scheduledByUserId   String?\n  sessionTypeId       String?\n  sessionType         SessionType? @relation(fields: [sessionTypeId], references: [id])\n  title               String\n  agenda              String?\n  startTime           DateTime\n  endTime             DateTime\n  originalStartTime   DateTime?\n  originalEndTime     DateTime?\n  durationHours       Float\n  isTrial             Boolean      @default(false)\n  status              String       @default(\"scheduled\")\n  sessionMode         String       @default(\"SCHEDULED\")\n  zoomLink            String?\n  zoomId              String?\n  zoomPasscode        String?\n  addedToCalendar     Boolean      @default(false)\n  calendarSyncedAt    DateTime?\n  recordingUrl        String?\n  transcriptUrl       String?\n  summaryUrl          String?\n  isActive            Boolean      @default(true)\n\n  attendances AmbassadorMeetingAttendance[]\n}\n\nmodel AmbassadorMeetingAttendance {\n  id                    String                  @id @default(cuid())\n  meetingId             String\n  meeting               AmbassadorMeeting       @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  ambassadorId          String\n  enrolmentItemId       String\n  enrolmentItem         AmbassadorEnrolmentItem @relation(fields: [enrolmentItemId], references: [id], onDelete: Cascade)\n  status                String\n  ambassadorLoggedHours Float\n  managementLoggedHours Float\n  hoursMatch            Boolean                 @default(true)\n  hoursMatchStatus      String?\n  noShowCount           Int                     @default(0)\n  changeRequestPending  Boolean                 @default(false)\n  changeRequestStatus   String?\n  feedbackStars         Int?\n  feedbackText          String?\n  feedbackGivenAt       DateTime?\n  notes                 String?\n  markedAt              DateTime?\n}\n\n// ─── CLUSTER 14 — CALENDAR SYSTEM ───────────────────────────────────────────\n\nmodel CalendarItem {\n  id           String    @id @default(cuid())\n  entityType   String // \"ACADEMIC_SESSION\" | \"MEETING\" | \"AMBASSADOR_MEETING\"\n  entityId     String\n  userId       String\n  user         User      @relation(fields: [userId], references: [id])\n  startTime    DateTime\n  endTime      DateTime\n  title        String\n  colour       String?\n  status       String\n  addedToGCal  Boolean   @default(false)\n  gCalSyncedAt DateTime?\n  gCalEventId  String?\n}\n\n// ─── CLUSTER 15 — CURRICULUM (STUDENT) ──────────────────────────────────────\n\nmodel CurriculumList {\n  id        String  @id @default(cuid())\n  serviceId String  @unique\n  service   Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n  isActive  Boolean @default(true)\n\n  syllabusLists SyllabusList[]\n  taskLists     TaskList[]\n  mockLists     MockList[]\n  timelineLists CourseTimelineList[]\n}\n\nmodel SyllabusList {\n  id               String         @id @default(cuid())\n  curriculumListId String\n  curriculumList   CurriculumList @relation(fields: [curriculumListId], references: [id], onDelete: Cascade)\n  name             String\n  version          String\n  level            String\n  status           String         @default(\"ACTIVE\")\n  activatedAt      DateTime       @default(now())\n  pausedAt         DateTime?\n  deactivatedAt    DateTime?\n  isActive         Boolean        @default(true)\n\n  syllabusItems SyllabusItem[]\n  history       SyllabusListStatusHistory[]\n}\n\nmodel SyllabusListStatusHistory {\n  id              String       @id @default(cuid())\n  syllabusListId  String\n  syllabusList    SyllabusList @relation(fields: [syllabusListId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime     @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel SyllabusItem {\n  id                 String       @id @default(cuid())\n  syllabusListId     String\n  syllabusList       SyllabusList @relation(fields: [syllabusListId], references: [id], onDelete: Cascade)\n  chapterNum         String\n  chapterTitle       String\n  topicCode          String?\n  topicTitle         String\n  level              String\n  order              Int\n  lectureCompleted   Boolean      @default(false)\n  pastPaperQCount    Int          @default(0)\n  marksLostInPPQ     Float        @default(0)\n  pastPaperNotesLink String?\n  difficultTopics    String?\n  note               String?\n  isActive           Boolean      @default(true)\n\n  progressList        StudentProgress[]\n  doubts              Doubt[]\n  taskItems           TaskItem[]\n  mockItems           MockItem[]\n  courseTimelineItems CourseTimelineItem[]\n}\n\nmodel StudentProgress {\n  id             String       @id @default(cuid())\n  studentId      String\n  student        User         @relation(fields: [studentId], references: [id])\n  syllabusItemId String\n  syllabusItem   SyllabusItem @relation(fields: [syllabusItemId], references: [id], onDelete: Cascade)\n  status         String\n  masteryPct     Int\n  updatedAt      DateTime     @updatedAt\n\n  @@unique([studentId, syllabusItemId])\n}\n\nmodel TaskType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n\n  taskItems TaskItem[]\n}\n\nmodel TaskList {\n  id               String         @id @default(cuid())\n  curriculumListId String\n  curriculumList   CurriculumList @relation(fields: [curriculumListId], references: [id], onDelete: Cascade)\n  isActive         Boolean        @default(true)\n\n  taskItems TaskItem[]\n}\n\nmodel TaskItem {\n  id             String           @id @default(cuid())\n  taskListId     String\n  taskList       TaskList         @relation(fields: [taskListId], references: [id], onDelete: Cascade)\n  taskTypeId     String\n  taskType       TaskType         @relation(fields: [taskTypeId], references: [id])\n  sessionId      String?\n  session        AcademicSession? @relation(fields: [sessionId], references: [id])\n  syllabusItemId String?\n  syllabusItem   SyllabusItem?    @relation(fields: [syllabusItemId], references: [id])\n  serviceId      String?\n  service        Service?         @relation(fields: [serviceId], references: [id])\n  title          String\n  description    String?\n  hwLink         String?\n  paperLink      String?\n  dueDate        DateTime\n  assignedToAll  Boolean          @default(false)\n  isActive       Boolean          @default(true)\n\n  assignments   TaskAssignment[]\n  submissions   TaskSubmission[]\n  timelineItems CourseTimelineItem[]\n}\n\nmodel TaskAssignment {\n  id         String   @id @default(cuid())\n  taskItemId String\n  taskItem   TaskItem @relation(fields: [taskItemId], references: [id], onDelete: Cascade)\n  studentId  String\n  student    User     @relation(fields: [studentId], references: [id])\n\n  @@unique([taskItemId, studentId])\n}\n\nmodel TaskSubmission {\n  id              String   @id @default(cuid())\n  taskItemId      String\n  taskItem        TaskItem @relation(fields: [taskItemId], references: [id], onDelete: Cascade)\n  studentId       String\n  student         User     @relation(fields: [studentId], references: [id])\n  status          String\n  totalMarks      Float\n  marksScored     Float\n  marksLost       Float\n  subtopicsLostOn String?\n  submissionLink  String?\n  notes           String?\n  submittedAt     DateTime @default(now())\n\n  @@unique([taskItemId, studentId])\n}\n\nmodel MockList {\n  id               String         @id @default(cuid())\n  curriculumListId String\n  curriculumList   CurriculumList @relation(fields: [curriculumListId], references: [id], onDelete: Cascade)\n  isActive         Boolean        @default(true)\n\n  mockItems MockItem[]\n}\n\nmodel MockItem {\n  id             String           @id @default(cuid())\n  mockListId     String\n  mockList       MockList         @relation(fields: [mockListId], references: [id], onDelete: Cascade)\n  sessionId      String?\n  session        AcademicSession? @relation(fields: [sessionId], references: [id])\n  syllabusItemId String?\n  syllabusItem   SyllabusItem?    @relation(fields: [syllabusItemId], references: [id])\n  serviceId      String?\n  service        Service?         @relation(fields: [serviceId], references: [id])\n  mockType       String\n  paperCode      String?\n  paperLink      String?\n  scheduledDate  DateTime\n  totalMarks     Float\n  isActive       Boolean          @default(true)\n\n  results       MockResult[]\n  timelineItems CourseTimelineItem[]\n}\n\nmodel MockResult {\n  id             String    @id @default(cuid())\n  mockItemId     String\n  mockItem       MockItem  @relation(fields: [mockItemId], references: [id], onDelete: Cascade)\n  studentId      String\n  student        User      @relation(fields: [studentId], references: [id])\n  marksScored    Float\n  marksAvailable Float\n  marksLost      Float\n  submissionLink String?\n  correctionLink String?\n  notes          String?\n  completed      Boolean   @default(false)\n  completedAt    DateTime?\n  serviceId      String?\n  service        Service?  @relation(fields: [serviceId], references: [id])\n\n  @@unique([mockItemId, studentId])\n  @@index([studentId])\n  @@index([serviceId])\n}\n\nmodel CourseTimelineList {\n  id               String         @id @default(cuid())\n  curriculumListId String\n  curriculumList   CurriculumList @relation(fields: [curriculumListId], references: [id], onDelete: Cascade)\n  isActive         Boolean        @default(true)\n\n  items CourseTimelineItem[]\n}\n\nmodel CourseTimelineItem {\n  id             String             @id @default(cuid())\n  timelineListId String\n  timelineList   CourseTimelineList @relation(fields: [timelineListId], references: [id], onDelete: Cascade)\n  month          String\n  weekNumber     Int\n  itemType       String\n  syllabusItemId String?\n  syllabusItem   SyllabusItem?      @relation(fields: [syllabusItemId], references: [id])\n  taskItemId     String?\n  taskItem       TaskItem?          @relation(fields: [taskItemId], references: [id])\n  mockItemId     String?\n  mockItem       MockItem?          @relation(fields: [mockItemId], references: [id])\n  notes          String?\n}\n\n// ─── CLUSTER 15B — CURRICULUM (AMBASSADOR) ──────────────────────────────────\n\nmodel AmbassadorProgrammeList {\n  id                  String  @id @default(cuid())\n  ambassadorServiceId String  @unique\n  isActive            Boolean @default(true)\n\n  programmes    AmbassadorProgramme[]\n  testLists     AmbassadorTestList[]\n  timelineLists AmbassadorProgrammeTimelineList[]\n}\n\nmodel AmbassadorProgramme {\n  id              String                  @id @default(cuid())\n  programmeListId String\n  programmeList   AmbassadorProgrammeList @relation(fields: [programmeListId], references: [id], onDelete: Cascade)\n  name            String\n  version         String\n  status          String\n  activatedAt     DateTime                @default(now())\n  pausedAt        DateTime?\n  deactivatedAt   DateTime?\n  isActive        Boolean                 @default(true)\n\n  items   AmbassadorProgrammeItem[]\n  history AmbassadorProgrammeListStatusHistory[]\n}\n\nmodel AmbassadorProgrammeListStatusHistory {\n  id              String              @id @default(cuid())\n  programmeListId String\n  programmeList   AmbassadorProgramme @relation(fields: [programmeListId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime            @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel AmbassadorProgrammeItem {\n  id             String              @id @default(cuid())\n  programmeId    String\n  programme      AmbassadorProgramme @relation(fields: [programmeId], references: [id], onDelete: Cascade)\n  programmeCode  String\n  programmeTitle String\n  level          String\n  order          Int\n  note           String?\n  isActive       Boolean             @default(true)\n\n  progressList  AmbassadorProgrammeProgress[]\n  testItems     AmbassadorTestItem[]\n  timelineItems AmbassadorProgrammeTimelineItem[]\n}\n\nmodel AmbassadorProgrammeProgress {\n  id              String                  @id @default(cuid())\n  ambassadorId    String\n  ambassador      User                    @relation(fields: [ambassadorId], references: [id])\n  programmeItemId String\n  programmeItem   AmbassadorProgrammeItem @relation(fields: [programmeItemId], references: [id], onDelete: Cascade)\n  status          String\n  masteryPct      Int\n  updatedAt       DateTime                @updatedAt\n\n  @@unique([ambassadorId, programmeItemId])\n}\n\nmodel AmbassadorTestList {\n  id              String                  @id @default(cuid())\n  programmeListId String\n  programmeList   AmbassadorProgrammeList @relation(fields: [programmeListId], references: [id], onDelete: Cascade)\n  isActive        Boolean                 @default(true)\n\n  testItems AmbassadorTestItem[]\n}\n\nmodel AmbassadorTestItem {\n  id              String                   @id @default(cuid())\n  testListId      String\n  testList        AmbassadorTestList       @relation(fields: [testListId], references: [id], onDelete: Cascade)\n  meetingId       String?\n  programmeItemId String?\n  programmeItem   AmbassadorProgrammeItem? @relation(fields: [programmeItemId], references: [id])\n  testType        String\n  paperLink       String?\n  scheduledDate   DateTime\n  totalMarks      Float\n  isActive        Boolean                  @default(true)\n\n  results       AmbassadorTestResult[]\n  timelineItems AmbassadorProgrammeTimelineItem[]\n}\n\nmodel AmbassadorTestResult {\n  id             String             @id @default(cuid())\n  testItemId     String\n  testItem       AmbassadorTestItem @relation(fields: [testItemId], references: [id], onDelete: Cascade)\n  ambassadorId   String\n  ambassador     User               @relation(fields: [ambassadorId], references: [id])\n  marksScored    Float\n  marksAvailable Float\n  marksLost      Float\n  submissionLink String?\n  notes          String?\n  completed      Boolean            @default(false)\n  completedAt    DateTime?\n\n  @@unique([testItemId, ambassadorId])\n}\n\nmodel AmbassadorProgrammeTimelineList {\n  id              String                  @id @default(cuid())\n  programmeListId String\n  programmeList   AmbassadorProgrammeList @relation(fields: [programmeListId], references: [id], onDelete: Cascade)\n  isActive        Boolean                 @default(true)\n\n  items AmbassadorProgrammeTimelineItem[]\n}\n\nmodel AmbassadorProgrammeTimelineItem {\n  id              String                          @id @default(cuid())\n  timelineListId  String\n  timelineList    AmbassadorProgrammeTimelineList @relation(fields: [timelineListId], references: [id], onDelete: Cascade)\n  month           String\n  weekNumber      Int\n  itemType        String\n  programmeItemId String?\n  programmeItem   AmbassadorProgrammeItem?        @relation(fields: [programmeItemId], references: [id])\n  taskItemId      String?\n  testItemId      String?\n  testItem        AmbassadorTestItem?             @relation(fields: [testItemId], references: [id])\n  notes           String?\n}\n\n// ─── CLUSTER 16 — REFERRALS ─────────────────────────────────────────────────\n\nmodel Referral {\n  id                String   @id @default(cuid())\n  referrerId        String\n  referrer          User     @relation(\"Referrer\", fields: [referrerId], references: [id])\n  referredStudentId String?\n  code              String\n  status            String   @default(\"pending\") // \"pending\"|\"enrolled\"|\"expired\"\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n\n  earnings AmbassadorEarning[]\n  clicks   ReferralClick[]\n\n  @@index([referrerId])\n}\n\nmodel ReferralClick {\n  id                   String   @id @default(cuid())\n  referralId           String\n  referral             Referral @relation(fields: [referralId], references: [id], onDelete: Cascade)\n  ipAddress            String?\n  userAgent            String?\n  clickedAt            DateTime @default(now())\n  convertedToEnquiry   Boolean  @default(false)\n  convertedToEnrolment Boolean  @default(false)\n}\n\n// ─── CLUSTER 17 — STUDENT INVOICING ─────────────────────────────────────────\n\nmodel InvoiceMonth {\n  id       String @id @default(cuid())\n  month    String @unique // \"Aug_of_2022\"\n  serialNo Int? // XLSX serial\n\n  invoices            StudentInvoice[]\n  claims              Claim[]\n  paychecks           Paycheck[]\n  ambassadorPaychecks AmbassadorPaycheck[]\n}\n\nmodel StudentInvoice {\n  id                        String         @id @default(cuid())\n  studentId                 String\n  student                   User           @relation(fields: [studentId], references: [id])\n  invoiceMonthId            String?\n  invoiceMonth              InvoiceMonth?  @relation(fields: [invoiceMonthId], references: [id])\n  receivingPaymentMethodId  String?\n  receivingPaymentMethod    PaymentMethod? @relation(fields: [receivingPaymentMethodId], references: [id])\n  month                     String // \"YYYY-MM\"\n  invoiceMode               String? // \"Tuition\" etc.\n  subtotal                  Float          @default(0)\n  discountApplied           Float          @default(0)\n  netAmount                 Float          @default(0)\n  dueAmount                 Float          @default(0)\n  currency                  String\n  paymentDone               Boolean        @default(false)\n  paymentDate               DateTime?\n  paymentMethod             String?\n  referenceNo               String?\n  reminderStage             Int            @default(0)\n  invoicePdfUrl             String?\n  paymentAcknowledgementMsg String?\n  paymentReminderMsg        String?\n  serialNo                  Int?\n  status                    String         @default(\"draft\") // \"draft\"|\"paid\"|\"overdue\"\n  isActive                  Boolean        @default(true)\n  issuedAt                  DateTime?\n  billingStart              DateTime?\n  billingEnd                DateTime?\n  createdAt                 DateTime       @default(now())\n  totalAmount               Float?\n\n  lineItems     InvoiceLineItem[]\n  ledgerEntries LedgerEntry[]\n  history       StudentInvoiceStatusChangeLog[]\n\n  @@index([studentId])\n}\n\nmodel StudentInvoiceStatusChangeLog {\n  id              String         @id @default(cuid())\n  invoiceId       String\n  invoice         StudentInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime       @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel InvoiceLineItem {\n  id                       String                @id @default(cuid())\n  invoiceId                String\n  invoice                  StudentInvoice        @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  lineType                 String? // \"batch_tuition\" | \"book\" etc.\n  enrolmentItemId          String?\n  enrolmentItem            StudentEnrolmentItem? @relation(fields: [enrolmentItemId], references: [id])\n  sessionId                String?\n  sessionDate              DateTime?\n  sessionStart             DateTime?\n  sessionEnd               DateTime?\n  originalSessionStart     DateTime?\n  originalSessionEnd       DateTime?\n  attendanceStatusSnapshot String?\n  isTrialSession           Boolean               @default(false)\n  sessionHours             Float?\n  rateSnapshot             Float?\n  groupCodeSnapshot        String?\n  teacherNameSnapshot      String?\n  serviceNameSnapshot      String?\n  currency                 String?\n  hoursOrQty               Float?\n  lineTotal                Float?\n  originalInvoiceId        String?\n  originalLineItemId       String?\n  correctionReason         String?\n  originalSessionDate      DateTime?\n  correctionAmount         Float?\n  description              String?\n  originalAmount           Float?\n  originalCurrency         String?\n  conversionRateUsed       Float?\n  convertedAmount          Float?\n\n  @@index([invoiceId])\n}\n\n// ─── CLUSTER 18 — CLAIMS & COMPENSATION ─────────────────────────────────────\n\nmodel Claim {\n  id                       String        @id @default(cuid())\n  userId                   String\n  user                     User          @relation(fields: [userId], references: [id])\n  enrolmentListId          String?\n  claimantType             String? // \"teacher\" | \"staff\"\n  month                    String // \"Apr_of_2026\"\n  dept                     String // Drives budget debits\n  sessions                 Int?\n  hours                    Float?\n  rateApplied              Float?\n  amount                   Float\n  currency                 String        @default(\"INR\")\n  receivingPaymentMethodId String?\n  status                   String        @default(\"pending\") // \"pending\"|\"approved\"|\"paid\"\n  notes                    String?\n  notes2                   String?\n  startDate                DateTime?\n  endDate                  DateTime?\n  paymentDate              DateTime?\n  isActive                 Boolean       @default(true)\n  createdAt                DateTime      @default(now())\n  invoiceMonthId           String?\n  invoiceMonth             InvoiceMonth? @relation(fields: [invoiceMonthId], references: [id])\n\n  ledgerEntries LedgerEntry[]\n  utilisations  BudgetUtilisation[]\n  history       ClaimStatusChangeLog[]\n  paychecks     Paycheck[]\n\n  @@index([userId])\n}\n\nmodel ClaimLineItem {\n  id                  String    @id @default(cuid())\n  claimId             String\n  serviceId           String?\n  service             Service?  @relation(fields: [serviceId], references: [id])\n  sessionId           String?\n  sessionDate         DateTime?\n  sessionStart        DateTime?\n  sessionEnd          DateTime?\n  sessionHours        Float?\n  staffRateSnapshot   Float?\n  lineTotal           Float\n  currency            String\n  serviceNameSnapshot String?\n  groupCodeSnapshot   String?\n}\n\nmodel ClaimStatusChangeLog {\n  id              String   @id @default(cuid())\n  claimId         String\n  claim           Claim    @relation(fields: [claimId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel Paycheck {\n  id                       String        @id @default(cuid())\n  claimId                  String?\n  claim                    Claim?        @relation(fields: [claimId], references: [id])\n  recipientId              String\n  recipient                User          @relation(\"PaycheckRecipient\", fields: [recipientId], references: [id])\n  enrolmentListId          String?\n  paycheckMonthId          String?\n  paycheckMonth            InvoiceMonth? @relation(fields: [paycheckMonthId], references: [id])\n  receivingPaymentMethodId String?\n  month                    String\n  paycheckMode             String?\n  subtotal                 Float         @default(0)\n  deductionsApplied        Float         @default(0)\n  netAmount                Float         @default(0)\n  dueAmount                Float         @default(0)\n  currency                 String\n  status                   String        @default(\"draft\")\n  statusReason             String?\n  isActive                 Boolean       @default(true)\n  notes                    String?\n  createdAt                DateTime      @default(now())\n\n  ledgerEntries LedgerEntry[]\n  history       PaycheckStatusChangeLog[]\n  lineItems     PaycheckLineItem[]\n}\n\nmodel PaycheckStatusChangeLog {\n  id              String   @id @default(cuid())\n  paycheckId      String\n  paycheck        Paycheck @relation(fields: [paycheckId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel PaycheckLineItem {\n  id                       String    @id @default(cuid())\n  paycheckId               String\n  paycheck                 Paycheck  @relation(fields: [paycheckId], references: [id], onDelete: Cascade)\n  lineType                 String // \"class\" | \"meeting\" | \"correction\"\n  enrolmentItemId          String?\n  sessionId                String?\n  meetingId                String?\n  eventDate                DateTime?\n  eventStart               DateTime?\n  eventEnd                 DateTime?\n  originalEventStart       DateTime?\n  originalEventEnd         DateTime?\n  attendanceStatusSnapshot String?\n  isTrialEvent             Boolean   @default(false)\n  eventHours               Float?\n  rateSnapshot             Float?\n  serviceTitleSnapshot     String?\n  originalPaycheckId       String?\n  originalLineItemId       String?\n  correctionReason         String?\n  originalEventDate        DateTime?\n  correctionAmount         Float?\n  originalAmount           Float?\n  originalCurrency         String?\n  conversionRateUsed       Float?\n  convertedAmount          Float?\n}\n\n// ─── CLUSTER 18B — AMBASSADOR CLAIMS & PAYCHECKS ────────────────────────────\n\nmodel AmbassadorClaim {\n  id                       String   @id @default(cuid())\n  ambassadorId             String\n  ambassador               User     @relation(fields: [ambassadorId], references: [id])\n  commissionListId         String?\n  month                    String\n  totalStudentAmountPaid   Float    @default(0)\n  commissionAmount         Float    @default(0)\n  currency                 String   @default(\"INR\")\n  receivingPaymentMethodId String?\n  status                   String   @default(\"pending\")\n  statusReason             String?\n  notes                    String?\n  isActive                 Boolean  @default(true)\n  createdAt                DateTime @default(now())\n\n  lineItems AmbassadorClaimLineItem[]\n  history   AmbassadorClaimStatusChangeLog[]\n  paychecks AmbassadorPaycheck[]\n}\n\nmodel AmbassadorClaimLineItem {\n  id                     String          @id @default(cuid())\n  claimId                String\n  claim                  AmbassadorClaim @relation(fields: [claimId], references: [id], onDelete: Cascade)\n  commissionItemId       String?\n  studentEnrolmentItemId String?\n  studentHoursLogged     Float?\n  studentAmountPaid      Float?\n  commissionPct          Float?\n  lineTotal              Float\n  currency               String\n}\n\nmodel AmbassadorClaimStatusChangeLog {\n  id              String          @id @default(cuid())\n  claimId         String\n  claim           AmbassadorClaim @relation(fields: [claimId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime        @default(now())\n  changedByUserId String\n  reason          String?\n}\n\nmodel AmbassadorPaycheck {\n  id                       String          @id @default(cuid())\n  claimId                  String\n  claim                    AmbassadorClaim @relation(fields: [claimId], references: [id], onDelete: Cascade)\n  ambassadorId             String\n  ambassador               User            @relation(fields: [ambassadorId], references: [id])\n  paycheckMonthId          String?\n  paycheckMonth            InvoiceMonth?   @relation(fields: [paycheckMonthId], references: [id])\n  receivingPaymentMethodId String?\n  month                    String\n  subtotal                 Float           @default(0)\n  dueAmount                Float           @default(0)\n  currency                 String\n  status                   String          @default(\"draft\")\n  statusReason             String?\n  isActive                 Boolean         @default(true)\n  notes                    String?\n  createdAt                DateTime        @default(now())\n\n  ledgerEntries LedgerEntry[]\n  history       AmbassadorPaycheckStatusChangeLog[]\n}\n\nmodel AmbassadorPaycheckStatusChangeLog {\n  id              String             @id @default(cuid())\n  paycheckId      String\n  paycheck        AmbassadorPaycheck @relation(fields: [paycheckId], references: [id], onDelete: Cascade)\n  fromStatus      String\n  toStatus        String\n  changedAt       DateTime           @default(now())\n  changedByUserId String\n  reason          String?\n}\n\n// ─── CLUSTER 19 — PAYMENT METHODS ───────────────────────────────────────────\n\nmodel PaymentMethodType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  region   String?\n  isActive Boolean @default(true)\n\n  methods PaymentMethod[]\n}\n\nmodel PaymentMethod {\n  id              String             @id @default(cuid())\n  createdByUserId String?\n  ownedByUserId   String?\n  typeId          String?\n  type            PaymentMethodType? @relation(fields: [typeId], references: [id])\n  label           String\n  reference       String?\n  currency        String\n  isActive        Boolean            @default(true)\n\n  bankAccounts      BankAccount[]\n  receivingInvoices StudentInvoice[]\n}\n\nmodel BankAccount {\n  id              String         @id @default(cuid())\n  ownerId         String?\n  owner           User?          @relation(fields: [ownerId], references: [id])\n  paymentMethodId String?        @unique\n  paymentMethod   PaymentMethod? @relation(fields: [paymentMethodId], references: [id])\n  isDcAccount     Boolean        @default(false)\n  label           String\n  purpose         String?\n  currency        String\n  currentBalance  Float          @default(0)\n  isActive        Boolean        @default(true)\n  bankName        String?\n  accountNumber   String?\n  ifscCode        String?\n  branchName      String?\n  paytmId         String?\n\n  deptBudgets   DeptBudget[]\n  ledgerEntries LedgerEntry[]\n  transactions  AccountTransaction[]\n}\n\nmodel PaymentRecord {\n  id                       String    @id @default(cuid())\n  entityType               String // \"STUDENT_INVOICE\" | \"PAYCHECK\" | \"AMBASSADOR_PAYCHECK\"\n  entityId                 String\n  receivingPaymentMethodId String?\n  paidByUserId             String?\n  paidByUser               User?     @relation(fields: [paidByUserId], references: [id])\n  payingPaymentMethodId    String?\n  amount                   Float\n  currency                 String\n  receiptLink              String?\n  stripePaymentIntentId    String?\n  status                   String    @default(\"pending\")\n  submittedAt              DateTime  @default(now())\n  paidAt                   DateTime?\n  receiverConfirmed        Boolean   @default(false)\n  confirmedByUserId        String?\n  confirmedAt              DateTime?\n  disputeReason            String?\n  notes                    String?\n}\n\n// ─── CLUSTER 20 — LEDGER, BUDGETS & DOUBLE-ENTRY ────────────────────────────\n\nmodel AccountTransaction {\n  id              String      @id @default(cuid())\n  bankAccountId   String\n  bankAccount     BankAccount @relation(fields: [bankAccountId], references: [id])\n  description     String\n  transactionType String // \"credit\" | \"debit\"\n  amount          Float\n  currency        String\n  createdAt       DateTime    @default(now())\n\n  ledgerEntries LedgerEntry[]\n}\n\nmodel LedgerEntry {\n  id                   String              @id @default(cuid())\n  transactionId        String?\n  transaction          AccountTransaction? @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  bankAccountId        String\n  bankAccount          BankAccount         @relation(fields: [bankAccountId], references: [id])\n  amount               Float\n  direction            String // \"debit\"|\"credit\"\n  purpose              String // \"revenue\"|\"claim_payment\"|\"operations_payment\"|\"budget_allocation\"\n  studentInvoiceId     String?\n  studentInvoice       StudentInvoice?     @relation(fields: [studentInvoiceId], references: [id])\n  claimId              String?\n  claim                Claim?              @relation(fields: [claimId], references: [id])\n  paycheckId           String?\n  paycheck             Paycheck?           @relation(fields: [paycheckId], references: [id])\n  ambassadorPaycheckId String?\n  ambassadorPaycheck   AmbassadorPaycheck? @relation(fields: [ambassadorPaycheckId], references: [id])\n  createdAt            DateTime            @default(now())\n\n  utilisations BudgetUtilisation[]\n}\n\nmodel DeptBudget {\n  id               String      @id @default(cuid())\n  dept             String // \"PR\"|\"HR\"|\"Finance\"|\"Marketing\"|\"IT\"|\"Management\"\n  quarter          String // \"2026-Q1\"|\"2026-Q2\"\n  totalAllocated   Float       @default(0)\n  status           String      @default(\"draft\") // \"draft\"|\"active\"|\"closed\"\n  bankAccountId    String\n  bankAccount      BankAccount @relation(fields: [bankAccountId], references: [id])\n  approvedByUserId String?\n  approvedAt       DateTime?\n  quarterStart     DateTime\n  quarterEnd       DateTime\n  isActive         Boolean     @default(true)\n  createdAt        DateTime    @default(now())\n\n  subCategories BudgetSubCategory[]\n\n  @@unique([dept, quarter])\n}\n\nmodel BudgetSubCategory {\n  id              String     @id @default(cuid())\n  budgetId        String\n  budget          DeptBudget @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n  subCategoryType String // \"claims\"|\"operations\"\n  allocated       Float      @default(0)\n  utilised        Float      @default(0)\n  remaining       Float      @default(0)\n  createdAt       DateTime   @default(now())\n\n  utilisations BudgetUtilisation[]\n\n  @@unique([budgetId, subCategoryType])\n}\n\nmodel BudgetUtilisation {\n  id            String            @id @default(cuid())\n  subCategoryId String\n  subCategory   BudgetSubCategory @relation(fields: [subCategoryId], references: [id])\n  ledgerEntryId String\n  ledgerEntry   LedgerEntry       @relation(fields: [ledgerEntryId], references: [id])\n  referenceType String // \"claim\"|\"invoice\"|\"ad_hoc\"\n  referenceId   String // references the source CUID\n  claimId       String?\n  claim         Claim?            @relation(fields: [claimId], references: [id])\n  amount        Float\n  createdAt     DateTime          @default(now())\n}\n\n// ─── CLUSTER 21 — TICKETING SYSTEM ──────────────────────────────────────────\n\nmodel Ticket {\n  id             String   @id @default(cuid())\n  displayId      String   @unique @default(\"PENDING\") // \"TKT-0042\"\n  title          String\n  description    String\n  status         String   @default(\"open\") // \"open\"|\"in_progress\"\n  priority       String   @default(\"normal\")\n  creatorId      String\n  creator        User     @relation(\"TicketCreator\", fields: [creatorId], references: [id])\n  assigneeId     String?\n  assignee       User?    @relation(\"TicketAssignee\", fields: [assigneeId], references: [id])\n  department     String? // \"PR\"|\"HR\"|\"Finance\"|\"Marketing\"|\"IT\"|\"Management\"\n  originalDept   String?\n  ticketType     String? // \"support\"|\"reschedule\"\n  attachmentLink String?\n  category       String?\n  routingStack   String?\n  isConfidential Boolean  @default(false)\n  isActive       Boolean  @default(true)\n  meta           String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  messages          TicketMessage[]\n  history           TicketHistory[]\n  studentRecords    StudentRecord[]\n  teacherRecords    TeacherRecord[]\n  ambassadorRecords AmbassadorRecord[]\n  staffRecords      StaffRecord[]\n  backlogItems      BacklogItem[]\n}\n\nmodel TicketCategory {\n  id         String   @id @default(cuid())\n  name       String\n  department String\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([name, department])\n}\n\nmodel TicketMessage {\n  id             String   @id @default(cuid())\n  ticketId       String\n  ticket         Ticket   @relation(fields: [ticketId], references: [id])\n  senderId       String\n  sender         User     @relation(fields: [senderId], references: [id])\n  body           String\n  isInternal     Boolean  @default(false)\n  attachmentLink String?\n  createdAt      DateTime @default(now())\n}\n\nmodel TicketHistory {\n  id        String   @id @default(cuid())\n  ticketId  String\n  ticket    Ticket   @relation(fields: [ticketId], references: [id])\n  actorId   String\n  actor     User     @relation(fields: [actorId], references: [id])\n  action    String\n  meta      String?\n  createdAt DateTime @default(now())\n}\n\nmodel TicketPermission {\n  id                  String   @id @default(cuid())\n  department          String   @unique\n  canTargetStudent    Boolean  @default(true)\n  canTargetParent     Boolean  @default(true)\n  canTargetTeacher    Boolean  @default(true)\n  canTargetAmbassador Boolean  @default(true)\n  canTargetCandidate  Boolean  @default(true)\n  canTargetPR         Boolean  @default(true)\n  canTargetIT         Boolean  @default(true)\n  canTargetHR         Boolean  @default(true)\n  canTargetFinance    Boolean  @default(true)\n  canTargetMarketing  Boolean  @default(true)\n  canTargetManagement Boolean  @default(true)\n  isInternalOnly      Boolean  @default(false)\n  updatedAt           DateTime @updatedAt\n}\n\n// ─── CLUSTER 22 — HR & FLAGS ────────────────────────────────────────────────\n\nmodel StudentRecord {\n  id                  String   @id @default(cuid())\n  userId              String\n  user                User     @relation(\"StudentRecordUser\", fields: [userId], references: [id], onDelete: Cascade)\n  recordType          String\n  triggeredByTicketId String?\n  triggeredByTicket   Ticket?  @relation(fields: [triggeredByTicketId], references: [id])\n  issuedByUserId      String?\n  issuedByUser        User?    @relation(\"StudentRecordIssuer\", fields: [issuedByUserId], references: [id])\n  notes               String?\n  documentLink        String?\n  issuedAt            DateTime @default(now())\n}\n\nmodel TeacherRecord {\n  id                  String   @id @default(cuid())\n  userId              String\n  user                User     @relation(\"TeacherRecordUser\", fields: [userId], references: [id], onDelete: Cascade)\n  recordType          String\n  triggeredByTicketId String?\n  triggeredByTicket   Ticket?  @relation(fields: [triggeredByTicketId], references: [id])\n  issuedByUserId      String?\n  issuedByUser        User?    @relation(\"TeacherRecordIssuer\", fields: [issuedByUserId], references: [id])\n  notes               String?\n  documentLink        String?\n  issuedAt            DateTime @default(now())\n}\n\nmodel AmbassadorRecord {\n  id                  String   @id @default(cuid())\n  userId              String\n  user                User     @relation(\"AmbassadorRecordUser\", fields: [userId], references: [id], onDelete: Cascade)\n  recordType          String\n  triggeredByTicketId String?\n  triggeredByTicket   Ticket?  @relation(fields: [triggeredByTicketId], references: [id])\n  issuedByUserId      String?\n  issuedByUser        User?    @relation(\"AmbassadorRecordIssuer\", fields: [issuedByUserId], references: [id])\n  notes               String?\n  documentLink        String?\n  issuedAt            DateTime @default(now())\n}\n\nmodel StaffRecord {\n  id                  String   @id @default(cuid())\n  userId              String\n  user                User     @relation(\"StaffRecordUser\", fields: [userId], references: [id], onDelete: Cascade)\n  recordType          String\n  triggeredByTicketId String?\n  triggeredByTicket   Ticket?  @relation(fields: [triggeredByTicketId], references: [id])\n  issuedByUserId      String?\n  issuedByUser        User?    @relation(\"StaffRecordIssuer\", fields: [issuedByUserId], references: [id])\n  notes               String?\n  documentLink        String?\n  issuedAt            DateTime @default(now())\n}\n\nmodel StudentFlag {\n  id               String    @id @default(cuid())\n  studentId        String\n  student          User      @relation(\"FlaggedUser\", fields: [studentId], references: [id], onDelete: Cascade)\n  flaggedByUserId  String\n  flaggedByUser    User      @relation(\"FlagCreator\", fields: [flaggedByUserId], references: [id])\n  flagType         String\n  flagSource       String?\n  notes            String?\n  resolved         Boolean   @default(false)\n  flaggedAt        DateTime  @default(now())\n  resolvedAt       DateTime?\n  resolvedByUserId String?\n}\n\n// ─── CLUSTER 23 — LOOKUP & LOOKUP TABLES ────────────────────────────────────\n\nmodel TicketType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel NotificationType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n\n  notifications Notification[]\n}\n\nmodel FlagType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel RecordType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel MockType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel AmbassadorTestType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel OutreachSource {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel SocialPlatformType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel SocialPostType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel CampaignTag {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n\n  campaigns Campaign[]\n}\n\n// ─── CLUSTER 24 — NOTIFICATIONS & COMMUNICATION ─────────────────────────────\n\nmodel Notification {\n  id                 String           @id @default(cuid())\n  userId             String\n  notificationTypeId String\n  notificationType   NotificationType @relation(fields: [notificationTypeId], references: [id])\n  title              String\n  body               String\n  entityType         String?\n  entityId           String?\n  read               Boolean          @default(false)\n  createdAt          DateTime         @default(now())\n}\n\n// ─── CLUSTER 25 — JOB POSTINGS & ADMISSIONS ──────────────────────────────────\n\nmodel JobPosting {\n  id                   String    @id @default(cuid())\n  role                 String\n  dept                 String\n  description          String\n  jobPostingLink       String?\n  jobPostingPosterLink String?\n  status               String\n  postedAt             DateTime?\n  closedAt             DateTime?\n  isActive             Boolean   @default(true)\n}\n\nmodel RegistrationForm {\n  id          String  @id @default(cuid())\n  name        String\n  targetRole  String\n  description String\n  isPublic    Boolean @default(false)\n  isActive    Boolean @default(true)\n\n  entries RegistrationFormEntry[]\n}\n\nmodel RegistrationFormEntry {\n  id                     String           @id @default(cuid())\n  formId                 String\n  form                   RegistrationForm @relation(fields: [formId], references: [id], onDelete: Cascade)\n  name                   String\n  email                  String\n  phone                  String?\n  country                String?\n  message                String?\n  cvLink                 String?\n  additionalData         String?\n  status                 String\n  convertedToCandidateId String?\n  convertedToCandidate   Candidate?       @relation(fields: [convertedToCandidateId], references: [id])\n  submittedAt            DateTime         @default(now())\n}\n\n// ─── CLUSTER 26 — CHECKLIST SYSTEM ──────────────────────────────────────────\n\nmodel ChecklistTemplate {\n  id         String  @id @default(cuid())\n  name       String\n  entityType String\n  targetRole String\n  isActive   Boolean @default(true)\n\n  items   ChecklistTemplateItem[]\n  entries ChecklistEntry[]\n}\n\nmodel ChecklistTemplateItem {\n  id         String            @id @default(cuid())\n  templateId String\n  template   ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  label      String\n  order      Int\n  isActive   Boolean           @default(true)\n\n  entries ChecklistItemEntry[]\n}\n\nmodel ChecklistEntry {\n  id          String            @id @default(cuid())\n  templateId  String\n  template    ChecklistTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  entityType  String\n  entityId    String\n  userId      String\n  user        User              @relation(fields: [userId], references: [id])\n  completed   Boolean           @default(false)\n  completedAt DateTime?\n\n  items ChecklistItemEntry[]\n}\n\nmodel ChecklistItemEntry {\n  id               String                @id @default(cuid())\n  checklistEntryId String\n  checklistEntry   ChecklistEntry        @relation(fields: [checklistEntryId], references: [id], onDelete: Cascade)\n  templateItemId   String\n  templateItem     ChecklistTemplateItem @relation(fields: [templateItemId], references: [id], onDelete: Cascade)\n  checked          Boolean               @default(false)\n  checkedAt        DateTime?\n}\n\n// ─── CLUSTER 27 — CAMPAIGNS & MARKETING ──────────────────────────────────────\n\nmodel Campaign {\n  id            String       @id @default(cuid())\n  name          String\n  description   String?\n  campaignTagId String?\n  campaignTag   CampaignTag? @relation(fields: [campaignTagId], references: [id])\n  startDate     DateTime?\n  endDate       DateTime?\n  status        String\n  isActive      Boolean      @default(true)\n\n  items CampaignItem[]\n}\n\nmodel CampaignItem {\n  id         String   @id @default(cuid())\n  campaignId String\n  campaign   Campaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)\n  itemType   String\n  entityId   String?\n  entityType String?\n  notes      String?\n  isActive   Boolean  @default(true)\n}\n\n// ─── CLUSTER 28 — OUTREACH & EXHIBITION ─────────────────────────────────────\n\nmodel OutreachType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n\n  items OutreachItem[]\n}\n\nmodel ExhibitionType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n\n  items ExhibitionItem[]\n}\n\nmodel OutreachItem {\n  id               String       @id @default(cuid())\n  outreachTypeId   String\n  outreachType     OutreachType @relation(fields: [outreachTypeId], references: [id])\n  title            String\n  targetAudience   String\n  assignedToUserId String\n  plannedDate      DateTime\n  completedAt      DateTime?\n  leadCount        Int          @default(0)\n  status           String\n  notes            String?\n  isActive         Boolean      @default(true)\n}\n\nmodel ExhibitionItem {\n  id               String         @id @default(cuid())\n  exhibitionTypeId String\n  exhibitionType   ExhibitionType @relation(fields: [exhibitionTypeId], references: [id])\n  title            String\n  venue            String\n  location         String\n  assignedToUserId String\n  plannedDate      DateTime\n  completedAt      DateTime?\n  leadCount        Int            @default(0)\n  status           String\n  notes            String?\n  isActive         Boolean        @default(true)\n}\n\n// ─── CLUSTER 29 — CONTENT & ANNOUNCEMENTS ───────────────────────────────────\n\nmodel ContentGroup {\n  id       String  @id @default(cuid())\n  name     String\n  dept     String\n  isActive Boolean @default(true)\n\n  items ContentGroupItem[]\n}\n\nmodel ContentGroupItem {\n  id                String          @id @default(cuid())\n  contentGroupId    String\n  contentGroup      ContentGroup    @relation(fields: [contentGroupId], references: [id], onDelete: Cascade)\n  contentBankItemId String\n  contentBankItem   ContentBankItem @relation(fields: [contentBankItemId], references: [id], onDelete: Cascade)\n}\n\nmodel ContentBankItem {\n  id            String    @id @default(cuid())\n  dept          String\n  name          String\n  url           String\n  addedByUserId String\n  addedBy       User      @relation(fields: [addedByUserId], references: [id])\n  isActive      Boolean   @default(true)\n  description   String?\n  dateAdded     DateTime?\n\n  groupItems ContentGroupItem[]\n}\n\nmodel Announcement {\n  id           String    @id @default(cuid())\n  title        String\n  body         String\n  targets      String? // comma separated roles\n  targetDept   String?\n  targetUserId String?\n  priority     String    @default(\"low\")\n  emailSent    Boolean   @default(false)\n  createdAt    DateTime  @default(now())\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  targetRole   String?   @default(\"all\")\n}\n\nmodel Recording {\n  id            String           @id @default(cuid())\n  serviceId     String?\n  service       Service?         @relation(fields: [serviceId], references: [id])\n  sessionId     String?\n  session       AcademicSession? @relation(fields: [sessionId], references: [id])\n  title         String\n  subject       String?\n  videoUrl      String\n  date          DateTime\n  durationHours Float?\n  duration      String?\n  category      String?\n  isActive      Boolean          @default(true)\n  createdAt     DateTime         @default(now())\n}\n\nmodel SiteLog {\n  id         String   @id @default(cuid())\n  userId     String?\n  user       User?    @relation(fields: [userId], references: [id])\n  action     String\n  entityType String?\n  entityId   String?\n  ipAddress  String?\n  userAgent  String?\n  device     String?\n  country    String?\n  metaBefore String?\n  metaAfter  String?\n  createdAt  DateTime @default(now())\n}\n\nmodel AccessLog {\n  id          String   @id @default(cuid())\n  staffId     String?\n  staff       User?    @relation(fields: [staffId], references: [id])\n  toolName    String\n  credential  String?\n  dateGranted DateTime @default(now())\n  revoked     Boolean  @default(false)\n  notes       String?\n  staffName   String?\n}\n\nmodel Doubt {\n  id             String       @id @default(cuid())\n  studentId      String\n  student        User         @relation(fields: [studentId], references: [id])\n  syllabusItemId String\n  syllabusItem   SyllabusItem @relation(fields: [syllabusItemId], references: [id], onDelete: Cascade)\n  body           String\n  response       String?\n  status         String       @default(\"open\")\n}\n\nmodel CurrencyRate {\n  id           String  @id @default(cuid())\n  fromCurrency String  @unique\n  toCurrency   String?\n  rate         Float\n  reverseRate  Float\n}\n\nmodel MarketingPost {\n  id            String   @id @default(cuid())\n  contentType   String?\n  status        String   @default(\"scheduled\")\n  canvaLink     String?\n  driveLink     String?\n  caption       String?\n  scheduledDate DateTime\n  campaignTag   String?\n  isActive      Boolean  @default(true)\n}\n\nmodel Lead {\n  id         String  @id @default(cuid())\n  name       String\n  email      String?\n  phone      String?\n  source     String?\n  status     String  @default(\"new\")\n  notes      String?\n  passedToPR Boolean @default(false)\n  isActive   Boolean @default(true)\n}\n\nmodel TextFormat {\n  id             String    @id @default(cuid())\n  name           String    @unique\n  text           String\n  alternateText1 String?\n  alternateText2 String?\n  dateAdded      DateTime?\n  use            String?\n  date           DateTime?\n}\n\nmodel BacklogItem {\n  id               String    @id @default(cuid())\n  serialNo         Int?\n  importance       String?\n  addedToCalendar  String?\n  addedToCalendar2 String?\n  dateAdded        DateTime?\n  date             DateTime?\n  additionalTask   String?\n  event            String?\n  desc             String?\n  startTime        String?\n  endTime          String?\n  durationHours    Float?\n  location         String?\n  tag              String?\n  nextSteps        String?\n  ticketId         String?\n  ticket           Ticket?   @relation(fields: [ticketId], references: [id])\n}\n\nmodel SprintItem {\n  id               String    @id @default(cuid())\n  serialNo         Int?\n  importance       String?\n  addedToCalendar  String?\n  addedToCalendar2 String?\n  dateAdded        DateTime?\n  date             DateTime?\n  additionalTask   String?\n  event            String?\n  desc             String?\n  startTime        String?\n  endTime          String?\n  durationHours    Float?\n  location         String?\n  tag              String?\n  nextSteps        String?\n}\n\nmodel AmbassadorDeliverable {\n  id           String            @id @default(cuid())\n  ambassadorId String\n  ambassador   AmbassadorProfile @relation(fields: [ambassadorId], references: [id], onDelete: Cascade)\n  title        String\n  score        Float?\n  status       String            @default(\"pending\")\n}\n\nmodel AmbassadorEarning {\n  id           String            @id @default(cuid())\n  ambassadorId String\n  ambassador   AmbassadorProfile @relation(fields: [ambassadorId], references: [id], onDelete: Cascade)\n  earningType  String\n  amount       Float\n  currency     String\n  payoutStatus String            @default(\"pending\")\n  referralId   String?\n  referral     Referral?         @relation(fields: [referralId], references: [id])\n}\n\nmodel ContentType {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel KnowledgeBankDomain {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel KnowledgeBankList {\n  id       String  @id @default(cuid())\n  domainId String\n  dept     String\n  isActive Boolean @default(true)\n}\n\nmodel KnowledgeBankItem {\n  id             String  @id @default(cuid())\n  listId         String\n  title          String\n  summary        String?\n  sourceTicketId String?\n  isActive       Boolean @default(true)\n}\n\nmodel OrgBacklogBank {\n  id       String  @id @default(cuid())\n  name     String  @unique\n  isActive Boolean @default(true)\n}\n\nmodel BacklogItemChangeLog {\n  id              String   @id @default(cuid())\n  backlogItemId   String\n  event           String\n  meetingId       String?\n  changedAt       DateTime @default(now())\n  changedByUserId String\n  notes           String?\n}\n\nmodel MeetingSprintList {\n  id        String         @id @default(cuid())\n  meetingId String         @unique\n  meeting   GeneralMeeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  isActive  Boolean        @default(true)\n}\n\nmodel MeetingSprintItem {\n  id            String  @id @default(cuid())\n  sprintListId  String\n  backlogItemId String\n  notes         String?\n}\n\nmodel MeetingBacklogList {\n  id        String         @id @default(cuid())\n  meetingId String         @unique\n  meeting   GeneralMeeting @relation(fields: [meetingId], references: [id], onDelete: Cascade)\n  isActive  Boolean        @default(true)\n}\n\nmodel MeetingBacklogItem {\n  id            String    @id @default(cuid())\n  backlogListId String\n  ticketId      String?\n  title         String\n  dept          String\n  priority      String\n  notes         String?\n  pushedToBank  Boolean   @default(false)\n  pushedAt      DateTime?\n}\n\nmodel GeneralMeeting {\n  id            String       @id @default(cuid())\n  title         String\n  dateTime      DateTime\n  agenda        String?\n  status        String       @default(\"scheduled\")\n  link          String?\n  dept          String?\n  isActive      Boolean      @default(true)\n  sessionTypeId String?\n  sessionType   SessionType? @relation(fields: [sessionTypeId], references: [id])\n\n  participants MeetingParticipant[] @relation(\"GeneralMeetingParticipants\")\n  sprintList   MeetingSprintList?\n  backlogList  MeetingBacklogList?\n}\n\nmodel Assignment {\n  id          String   @id @default(cuid())\n  title       String\n  description String?\n  dueDate     DateTime\n  status      String   @default(\"pending\")\n  grade       String?\n  submission  String?\n  studentId   String\n  student     User     @relation(fields: [studentId], references: [id])\n  serviceId   String?\n  service     Service? @relation(fields: [serviceId], references: [id])\n\n  @@index([studentId])\n  @@index([serviceId])\n}\n\nmodel StudentStatus {\n  id         String  @id @default(cuid())\n  name       String  @unique\n  definition String?\n}\n\nmodel CanvaDesign {\n  id   String    @id @default(cuid())\n  name String\n  date DateTime?\n  link String\n}\n\nmodel Booklet {\n  id   String    @id @default(cuid())\n  name String\n  date DateTime?\n  link String\n}\n\nmodel GcrClassroom {\n  id       String    @id @default(cuid())\n  name     String\n  link     String\n  date     DateTime?\n  serialNo Int?\n}\n"
}

